    co = []
    for i in range(4):
        a = des0(u[:, i])
        b = fit(u[:, i], v[:, i])
        for _ in range(8):
            idx = np.argsort(abs(a @ b - v[:, i]))[:38]
            b = ls(a[idx], v[idx, i])
        co.append(b)
